import random
import subprocess
from typing import Optional, Dict, Any
from pydantic import BaseModel, Field
from smolagents import Tool


#################
## GLOBAL TOOLS
################


class TestRunnerTool(Tool):
    name = "test_runner"
    description = "Runs pytest and returns coverage percentage."
    inputs = {"path": {"type": "string", "description": "path to project"}}
    output_type = "string"

    def forward(self, path: str):
        print(f"TestRunnerTool called with path: {path}")
        try:
            result = subprocess.run(
                ["pytest", "--cov", path, "--cov-report=term-missing"],
                capture_output=True,
                text=True,
                cwd=path
            )
            output = result.stdout + result.stderr
            # Try to extract coverage percentage from output
            for line in output.splitlines():
                if "TOTAL" in line:
                    parts = line.split()
                    if parts:
                        return f"Test coverage: {parts[-1]}"
            return f"Test output:\n{output}"
        except Exception as e:
            return f"Test runner error: {str(e)}"


class FileEditorTool(Tool):
    name = "file_editor"
    description = "Edits files in a given project."
    inputs = {
        "path": {"type": "string", "description": "path to the file to edit"},
        "content": {"type": "string", "description": "new content for the file"}
    }
    output_type = "string"

    def forward(self, path: str, content: str):
        print(f"FileEditorTool called with path: {path}, content length: {len(content)}")
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(content)
            return f"File '{path}' edited successfully with new content length: {len(content)}"
        except Exception as e:
            return f"File editor error: {str(e)}"


class TerminalTool(Tool):
    name = "terminal_tool"
    description = "Executes terminal commands in a given project."
    inputs = {
        "command": {"type": "string", "description": "command to execute"},
        "cwd": {"type": "string", "description": "working directory for the command (optional)"}
    }
    output_type = "string"

    def forward(self, command: str, cwd: str = None):
        print(f"TerminalTool executing command: {command} in cwd: {cwd}")
        try:
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                cwd=cwd
            )
            output = result.stdout
            if result.stderr:
                output += f"\nSTDERR:\n{result.stderr}"
            if result.returncode != 0:
                output += f"\nReturn code: {result.returncode}"
            return output or f"Command executed successfully: {command}"
        except Exception as e:
            return f"Terminal tool error: {str(e)}"


class DockerTool(Tool):
    name = "docker_tool"
    description = "Manages Docker containers and images."
    inputs = {
        "action": {"type": "string", "description": "action to perform (e.g. build, run, stop, ps, logs)"},
        "options": {"type": "string", "description": "options for the action (e.g. image name, container id, flags)"}
    }
    output_type = "string"

    def forward(self, action: str, options: str):
        print(f"DockerTool called with action: {action}, options: {options}")
        try:
            command = f"docker {action} {options}"
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True
            )
            output = result.stdout
            if result.stderr:
                output += f"\nSTDERR:\n{result.stderr}"
            if result.returncode != 0:
                output += f"\nReturn code: {result.returncode}"
            return output or f"Docker action '{action}' performed successfully with options: {options}"
        except Exception as e:
            return f"Docker tool error: {str(e)}"


##############
## UTILS
#############

# Global tool registry mapping tool names to their classes
TOOL_REGISTRY: Dict[str, type] = {
    "test_runner": TestRunnerTool,
    "file_editor": FileEditorTool,
    "terminal_tool": TerminalTool,
    "docker_tool": DockerTool,
}


def register_tool(tool_cls: type) -> type:
    """Decorator or utility to register a tool class in the global registry."""
    TOOL_REGISTRY[tool_cls.name] = tool_cls
    return tool_cls


class FlowTool(BaseModel):
    """Flow yaml section to define the tools associated with a flow"""
    name: str = Field(description="The tool name that will be used to find in the tool_set")
    custom_args: Optional[dict] = Field(default={}, description="User arguments to be passed to the tool")


class FlowToolExecutor(Tool):
    """Based on a FlowTool settings will find the tool and execute it."""

    name = "flow_tool_executor"
    description = "Executes a tool based on FlowTool configuration, merging custom args with runtime args."
    inputs = {
        "kwargs": {
            "type": "string",
            "description": "JSON string of keyword arguments to pass to the underlying tool"
        }
    }
    output_type = "string"

    def __init__(self, flow_tool: FlowTool):
        super().__init__()
        self.flow_tool = flow_tool
        # Dynamically update name and description based on the wrapped tool
        tool_cls = TOOL_REGISTRY.get(flow_tool.name)
        if tool_cls:
            wrapped = tool_cls()
            self.name = f"flow_{flow_tool.name}"
            self.description = f"[FlowToolExecutor] {wrapped.description}"
            self.inputs = wrapped.inputs
            self._wrapped_tool: Tool = wrapped
        else:
            raise ValueError(
                f"Tool '{flow_tool.name}' not found in TOOL_REGISTRY. "
                f"Available tools: {list(TOOL_REGISTRY.keys())}"
            )

    def forward(self, **kwargs) -> str:
        """
        Execute the underlying tool by merging runtime kwargs with custom_args
        from FlowTool config. custom_args take precedence over runtime kwargs.
        """
        tool_name = self.flow_tool.name
        custom_args = self.flow_tool.custom_args or {}

        # Merge: runtime kwargs first, then custom_args override
        tool_args = {**kwargs, **custom_args}

        print(f"FlowToolExecutor executing '{tool_name}' with args: {tool_args}")

        try:
            result = self._wrapped_tool.forward(**tool_args)
            return result
        except Exception as e:
            return f"FlowToolExecutor error while executing '{tool_name}': {str(e)}"


##############
## EXAMPLE USAGE
#############

if __name__ == "__main__":
    # Example: Using FlowTool + FlowToolExecutor
    flow_tool_config = FlowTool(
        name="terminal_tool",
        custom_args={"cwd": "/home/codx-junior-projects/codx-junior"}
    )

    executor = FlowToolExecutor(flow_tool=flow_tool_config)
    output = executor.forward(command="ls -la")
    print(output)
